    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]
    N = len(S)

    size = 1 << N
    chars = [ord(ch) - 97 for ch in S]

    # Precompute transitions for all masks.
    # A mask represents the differences dp[j] - dp[j-1] of the LCS DP row.
    trans = []
    for mask in range(size):
        dp = [0] * (N + 1)
        v = 0
        for j in range(N):
            if (mask >> j) & 1:
                v += 1
            dp[j + 1] = v

        agg = {}
        for c in range(26):
            prev_new = 0
            next_mask = 0

            for j in range(1, N + 1):
                val = dp[j]
                if prev_new > val:
                    val = prev_new

                if chars[j - 1] == c:
                    cand = dp[j - 1] + 1
                    if cand > val:
                        val = cand

                if val > prev_new:
                    next_mask |= 1 << (j - 1)

                prev_new = val

            agg[next_mask] = agg.get(next_mask, 0) + 1

        trans.append(list(agg.items()))

    # popcount for masks
    pop = [0] * size
    for i in range(1, size):
        pop[i] = pop[i >> 1] + (i & 1)

    cur = [0] * size
    cur[0] = 1

    for _ in range(M):
        nxt = [0] * size

        for mask, cnt in enumerate(cur):
            if cnt:
                for next_mask, mult in trans[mask]:
                    nxt[next_mask] += cnt * mult

        for i in range(size):
            nxt[i] %= MOD

        cur = nxt

    ans = [0] * (N + 1)
    for mask, cnt in enumerate(cur):
        if cnt:
            k = pop[mask]
            ans[k] += cnt
            if ans[k] >= MOD:
                ans[k] -= MOD

    print(" ".join(map(str, ans)))

