def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, X = data[0], data[1]

    U = [0] * N
    D = [0] * N

    total = 0
    min_sum = 10**30

    idx = 2
    for i in range(N):
        u = data[idx]
        d = data[idx + 1]
        idx += 2

        U[i] = u
        D[i] = d

        s = u + d
        total += s
        if s < min_sum:
            min_sum = s

    del data

    rng = range(1, N)

    def feasible(H, UU=U, DD=D, X=X, rng=rng):
        u0 = UU[0]
        d0 = DD[0]

        if H > d0:
            l = H - d0
        else:
            l = 0

        if u0 < H:
            r = u0
        else:
            r = H

        for i in rng:
            u = UU[i]
            d = DD[i]

            if H > d:
                lo = H - d
            else:
                lo = 0

            if u < H:
                hi = u
            else:
                hi = H

            l -= X
            if lo > l:
                l = lo

            r += X
            if hi < r:
                r = hi

            if l > r:
                return False

        return True

    low = 0
    high = min_sum

    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1

    answer = total - N * low
    sys.stdout.write(str(answer) + "\n")


