import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    n = int(data[0])

    # dp_odd: maximum sum of a valid chosen prefix with odd length
    # dp_even: maximum sum of a valid chosen prefix with even length
    dp_odd = None
    dp_even = None

    for i in range(1, n + 1):
        x = int(data[i])

        if i & 1:
            # A valid prefix of odd length can start at this odd index,
            # or extend a valid even-length prefix.
            best = x

            if dp_even is not None:
                cand = dp_even + x
                if cand > best:
                    best = cand

            if dp_odd is not None and dp_odd > best:
                best = dp_odd

            dp_odd = best

        else:
            # A valid prefix of even length can only extend an odd-length prefix.
            if dp_odd is not None:
                cand = dp_odd + x
                if dp_even is None or cand > dp_even:
                    dp_even = cand

    if n & 1:
        # For odd N, the final stack size must be odd.
        print(dp_odd)
    else:
        # For even N, the final stack may also be empty.
        print(max(0, dp_even) if dp_even is not None else 0)

