def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    adj = [[] for _ in range(N)]
    for _ in range(M):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        w = int(next(it))
        adj[u].append((v, w))
        adj[v].append((u, w))

    target = N - 1
    ans = (1 << 61) - 1

    def dfs(u, visited_mask, current_xor):
        nonlocal ans

        if u == target:
            if current_xor < ans:
                ans = current_xor
            return

        for v, w in adj[u]:
            if not (visited_mask >> v) & 1:
                dfs(v, visited_mask | (1 << v), current_xor ^ w)

    dfs(0, 1, 0)
    print(ans)

